def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    color, fill = grid[0][0], 2
    # The outlined color is the nonzero color used in the grid.
    colors = {v for row in grid for v in row if v != 0}
    if not colors:
        return out
    color = next(iter(colors))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != color:
                continue
            for dr in (-1, 1):
                for d in range(1, h + w):
                    rr = r + dr * d
                    if not 0 <= rr < h:
                        break
                    left, right = c - d, c + d
                    left_inside = 0 <= left < w
                    right_inside = 0 <= right < w
                    if not left_inside and not right_inside:
                        break
                    if left_inside and grid[rr][left] != color:
                        break
                    if right_inside and grid[rr][right] != color:
                        break

                    for cc in range(max(0, left + 1), min(w, right)):
                        if grid[rr][cc] == 0:
                            out[rr][cc] = fill
    return out
